import{_ as s,c as i,a2 as e,o as l}from"./chunks/framework.BnrAgU0Y.js";const c=JSON.parse('{"title":"安装 Langflow","description":"安装 Langflow","frontmatter":{"title":"安装 Langflow","description":"安装 Langflow","layout":"doc"},"headers":[],"relativePath":"langflow/get-started-installation.md","filePath":"langflow/get-started-installation.md"}'),n={name:"langflow/get-started-installation.md"};function t(p,a,r,o,h,d){return l(),i("div",null,a[0]||(a[0]=[e('<h1 id="安装-langflow" tabindex="-1">安装 Langflow <a class="header-anchor" href="#安装-langflow" aria-label="Permalink to &quot;安装 Langflow&quot;">​</a></h1><p>您可以将 Langflow 部署在本地，或者使用 <a href="#datastax-langflow"><strong>Datastax Langflow</strong></a> 作为托管服务。</p><h2 id="安装-langflow-到本地" tabindex="-1">安装 Langflow 到本地 <a class="header-anchor" href="#安装-langflow-到本地" aria-label="Permalink to &quot;安装 Langflow 到本地&quot;">​</a></h2><p>可以通过 <a href="https://docs.astral.sh/uv/getting-started/installation/" target="_blank" rel="noreferrer">uv（推荐）</a>、<a href="https://pypi.org/project/pip/" target="_blank" rel="noreferrer">pip</a>、或 <a href="https://pipx.pypa.io/stable/installation/" target="_blank" rel="noreferrer">pipx</a> 将 Langflow 安装到本地。</p><h3 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>安装 <a href="https://www.python.org/downloads/release/python-3100/" target="_blank" rel="noreferrer">Python 3.10 到 3.12</a></li><li>安装 <a href="https://docs.astral.sh/uv/getting-started/installation/" target="_blank" rel="noreferrer">uv</a>、<a href="https://pypi.org/project/pip/" target="_blank" rel="noreferrer">pip</a>、或 <a href="https://pipx.pypa.io/stable/installation/" target="_blank" rel="noreferrer">pipx</a></li><li>在安装 Langflow 之前，我们建议使用 <a href="https://docs.astral.sh/uv/pip/environments" target="_blank" rel="noreferrer">uv</a>、<a href="https://docs.python.org/3/library/venv.html" target="_blank" rel="noreferrer">venv</a>、或 <a href="https://anaconda.org/anaconda/conda" target="_blank" rel="noreferrer">conda</a> 创建一个虚拟环境来隔离你的 Python 依赖项</li></ul><h3 id="使用-pip-或-pipx-安装-langflow" tabindex="-1">使用 pip 或 pipx 安装 Langflow <a class="header-anchor" href="#使用-pip-或-pipx-安装-langflow" aria-label="Permalink to &quot;使用 pip 或 pipx 安装 Langflow&quot;">​</a></h3><p>安装带有 uv 的 Langflow：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> langflow</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>使用 pip 安装 Langflow：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> langflow</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>使用 pipx 并指定 Python 3.10 可执行文件来安装 Langflow：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pipx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> langflow</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3.10</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="运行-langflow" tabindex="-1">运行 Langflow <a class="header-anchor" href="#运行-langflow" aria-label="Permalink to &quot;运行 Langflow&quot;">​</a></h2><ol><li><p>要使用 <code>uv</code> 运行 Langflow，输入以下命令。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> langflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>要使用 <code>pip</code> 运行 Langflow，输入以下命令。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> langflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>确认本地 Langflow 实例已启动，打开 Chromium 内核浏览器访问 <code>http://127.0.0.1:7860</code>。</p></li></ol><p>现在 Langflow 已经运行，接下来请参阅<a href="./URL.html">快速开始</a>以创建您的第一个 flow。</p><h2 id="管理-langflow-版本" tabindex="-1">管理 Langflow 版本 <a class="header-anchor" href="#管理-langflow-版本" aria-label="Permalink to &quot;管理 Langflow 版本&quot;">​</a></h2><p>要使用 uv 命令将 Langflow 升级到最新版本，请使用 uv pip 升级命令。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> langflow</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>要将 Langflow 升级到最新版本，请使用 pip 升级命令。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> langflow</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>要安装特定版本的 Langflow 包，请在命令中添加所需版本。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> langflow==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>要重新安装 Langflow 及其所有依赖项，请在命令中添加 <code>--force-reinstall</code> 标志。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> langflow</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-reinstall</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="datastax-langflow" tabindex="-1">DataStax Langflow <a class="header-anchor" href="#datastax-langflow" aria-label="Permalink to &quot;DataStax Langflow&quot;">​</a></h2><p><strong>DataStax Langflow</strong> 是托管版的Langflow，与 <a href="https://www.datastax.com/products/datastax-astra" target="_blank" rel="noreferrer">Astra DB</a> 集成。无需安装或设置，只需几分钟即可启动并运行。 <a href="https://astra.datastax.com/signup?type=langflow" target="_blank" rel="noreferrer">免费注册</a>。</p><h2 id="常见安装问题" tabindex="-1">常见安装问题 <a class="header-anchor" href="#常见安装问题" aria-label="Permalink to &quot;常见安装问题&quot;">​</a></h2><p>这是安装和运行 Langflow 时可能遇到的问题清单。</p><h3 id="no-langflow-main-模块" tabindex="-1">No <code>langflow.__main__</code> 模块 <a class="header-anchor" href="#no-langflow-main-模块" aria-label="Permalink to &quot;No `langflow.__main__` 模块&quot;">​</a></h3><p>当你尝试使用命令 <code>langflow run</code> 运行 Langflow 时，会遇到以下错误：</p><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; No module named &#39;langflow.__main__&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol><li>请运行 <code>python -m langflow run</code>，而不是 <code>langflow run</code>。</li><li>如果这不起作用，请使用 <code>python -m pip install langflow -U</code> 重新安装最新版本的 Langflow。</li><li>如果仍然无效，请使用 <code>python -m pip install langflow --pre -U --force-reinstall</code> 重新安装 Langflow 及其依赖项。</li></ol><h3 id="langflow-runtraceback" tabindex="-1">Langflow runTraceback <a class="header-anchor" href="#langflow-runtraceback" aria-label="Permalink to &quot;Langflow runTraceback&quot;">​</a></h3><p>当你尝试使用命令 <code>langflow run</code> 运行 Langflow 时，会遇到以下错误：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> langflow runTraceback (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">most</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> recent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> last</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">): File </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.../langflow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, line 5, in </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">module</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  from langflow.__main__ import mainModuleNotFoundError: No module named </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;langflow.__main__&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>此错误可能有两个原因：</p><ol><li><p>你通过 <code>pip install langflow</code> 安装了 Langflow，但系统中已经安装了以前版本的 Langflow。在这种情况下，你可能运行了错误的可执行文件。为了解决这个问题，请运行正确的可执行文件，使用命令 <code>python -m langflow run</code> 替代 <code>langflow run</code>。如果这不起作用，尝试卸载并重新安装 Langflow，使用 <code>python -m pip install langflow --pre -U</code>。</p></li><li><p>在安装过程中可能发生了一些版本冲突。运行 <code>python -m pip install langflow --pre -U --force-reinstall</code> 以重新安装 Langflow 及其依赖项。</p></li></ol><h3 id="运行迁移时出错" tabindex="-1">运行迁移时出错 <a class="header-anchor" href="#运行迁移时出错" aria-label="Permalink to &quot;运行迁移时出错&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>10 &gt; Something went wrong running migrations. Please, run &#39;langflow migration --fix&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>清除缓存可以通过删除缓存文件夹的内容来实现。</p><p>此文件夹的位置如下：</p><ul><li><strong>Linux 或 Windows 上的 WSL2</strong>: <code>home/&lt;用户名&gt;/.cache/langflow/</code></li><li><strong>MacOS</strong>: <code>/Users/&lt;用户名&gt;/Library/Caches/langflow/</code></li></ul><p>这个错误可能发生在 Langflow 升级时，由于新版本无法覆盖 <code>.cache/langflow/</code> 中的 <code>langflow-pre.db</code> 文件。清除缓存会移除该文件，但同时也会清除您的设置。</p><p>如果您希望保留文件，请在清除文件夹之前备份。</p><h3 id="langflow安装在pip依赖解析时冻结" tabindex="-1">Langflow安装在pip依赖解析时冻结 <a class="header-anchor" href="#langflow安装在pip依赖解析时冻结" aria-label="Permalink to &quot;Langflow安装在pip依赖解析时冻结&quot;">​</a></h3><p>使用 <code>pip install langflow</code> 进行Langflow安装时会缓慢失败，并出现以下错误信息：</p><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pip is looking at multiple versions of &lt;&lt;library&gt;&gt; to determine which version is compatible with other requirements. This could take a while.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>要解决此问题，请使用 <a href="https://docs.astral.sh/uv/getting-started/installation/" target="_blank" rel="noreferrer">uv</a> 来代替 <code>pip</code> 安装Langflow。</p><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uv pip install langflow</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>要使用uv运行Langflow：</p><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uv run langflow run</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>',52)]))}const k=s(n,[["render",t]]);export{c as __pageData,k as default};
